    _gDir.first = 0;
    _gDir.hFind = 0;

    char search[260];
    int i = 0;
    while (i < 260) { search[i] = 0; i++; }

    char* s = search; 
    char* p = path;
    
    // Copy path
    while (*p != 0) { 
        *s = *p; 
        s++; 
