    function scanLocals(stmts) {
        for (const s of stmts) {
            if (s.type === 'decl') {
                let size = 8;
                if (s.varType.ptr === 0) {
                     const sl = ctx.structLayouts.get(s.varType.base);
                     if (sl) size = sl.size;
                     else {
