                localOffset += size;
                while(localOffset % 8 !== 0) localOffset++;
                
                locals.set(s.name, { 
                    type: 'local', 
                    offset: -localOffset,
                    varType: s.varType,
                    isArray: s.arraySize > 0,
                    size: size
                });
            }
            if (s.type === 'block') scanLocals(s.stmts);
            if (s.type === 'if') { 
                if (s.then.type === 'block') scanLocals(s.then.stmts);
                if (s.el && s.el.type === 'block') scanLocals(s.el.stmts);
            }
